// branding.js — logo compartido RPT ("con tecnología de") + logo propio
// de cada club, para usar en entrenador.html y atleta.html.
const RPT_LOGO_B64 = '';

function injectBrandStyles(){
  if (document.getElementById('brandStripStyles')) return;
  const style = document.createElement('style');
  style.id = 'brandStripStyles';
  style.textContent = `
    .brandStrip{ display:flex; align-items:center; justify-content:space-between; gap:10px; padding:10px 16px; background:#20242e; }
    .brandStrip .clubSide{ display:flex; align-items:center; gap:8px; min-width:0; }
    .brandStrip .clubLogoImg{ height:28px; max-width:120px; object-fit:contain; border-radius:4px; }
    .brandStrip .clubNameText{ color:#f4f1ea; font-family:'Oswald',sans-serif; font-weight:700; font-size:14px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
    .brandStrip .poweredBy{ display:flex; align-items:center; gap:6px; flex-shrink:0; }
    .brandStrip .poweredByText{ color:#8892a0; font-size:10px; font-family:Inter,sans-serif; white-space:nowrap; }
    .brandStrip .rptMarkImg{ height:20px; width:auto; border-radius:3px; }
  `;
  document.head.appendChild(style);
}

// clubLogoUrl y clubName son opcionales — si no hay logo de club, solo se
// ve la marca de RPT.
function renderBrandStrip(clubLogoUrl, clubName){
  injectBrandStyles();
  const strip = document.createElement('div');
  strip.className = 'brandStrip';
  const clubSide = document.createElement('div');
  clubSide.className = 'clubSide';
  if (clubLogoUrl){
    const img = document.createElement('img');
    img.className = 'clubLogoImg';
    img.src = clubLogoUrl;
    img.alt = 'Logo del club';
    img.onerror = ()=>{ img.style.display = 'none'; };
    clubSide.appendChild(img);
  }
  if (clubName){
    const nameEl = document.createElement('span');
    nameEl.className = 'clubNameText';
    nameEl.textContent = clubName;
    clubSide.appendChild(nameEl);
  }
  strip.appendChild(clubSide);

  const powered = document.createElement('div');
  powered.className = 'poweredBy';
  powered.innerHTML = '<span class="poweredByText">con tecnología de</span>';
  const rptImg = document.createElement('img');
  rptImg.className = 'rptMarkImg';
  rptImg.src = 'data:image/png;base64,' + RPT_LOGO_B64;
  rptImg.alt = 'RPT';
  powered.appendChild(rptImg);
  strip.appendChild(powered);

  return strip;
}
